28: /// The colour seen along a ray: the surface normal where it hits, the sky gradient otherwise.
29: fn ray_colour(ray: &Ray, world: &dyn Hittable) -> Colour {
30:     if let Some(hit) = world.hit(ray, 0.001, f64::INFINITY) {
31:         return (hit.normal + Vec3::new(1.0, 1.0, 1.0)) * 0.5;
32:     }
33:     let t = 0.5 * (ray.direction.unit().y + 1.0);
34:     Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
35: }
