37: fn scene() -> HittableList {
38:     let mut world = HittableList::default();
39:     world.add(Box::new(Sphere::new(Vec3::new(0.0, 0.0, -1.0), 0.5)));
40:     world.add(Box::new(Sphere::new(Vec3::new(0.0, -100.5, -1.0), 100.0)));
41:     world
42: }
