44: /// Every pixel's colour, row by row from the top. A progress line on standard error reports the
45: /// share of rows done.
46: fn render(width: usize, height: usize, samples: usize) -> Vec<Colour> {
47:     let world = scene();
48:     let camera = Camera::new(width as f64 / height as f64);
49:     let mut pixels = Vec::with_capacity(width * height);
50:     for (done, row) in (0..height).rev().enumerate() {
51:         for column in 0..width {
52:             let u = column as f64 / (width - 1) as f64;
53:             let v = row as f64 / (height - 1) as f64;
54:             let ray = camera.ray(u, v);
55:             let mut colour = Colour::new(0.0, 0.0, 0.0);
56:             for _ in 0..samples {
57:                 colour = colour + ray_colour(&ray, &world);
58:             }
59:             pixels.push(colour / samples as f64);
60:         }
61:         eprint!("\r{:3}%", (done + 1) * 100 / height);
62:     }
63:     eprintln!();
64:     pixels
65: }
66: 
67: fn to_byte(channel: f64) -> u8 {
68:     (255.999 * channel.clamp(0.0, 1.0)) as u8
69: }
