71: fn write_ppm(
72:     out: &mut impl Write,
73:     width: usize,
74:     height: usize,
75:     pixels: &[Colour],
76: ) -> io::Result<()> {
77:     writeln!(out, "P3\n{width} {height}\n255")?;
78:     for pixel in pixels {
79:         writeln!(
80:             out,
81:             "{} {} {}",
82:             to_byte(pixel.x),
83:             to_byte(pixel.y),
84:             to_byte(pixel.z)
85:         )?;
86:     }
87:     Ok(())
