117: impl Config {
118:     /// Parse the command-line options, rejecting a missing value, a bad number and an unknown option.
119:     fn parse(args: impl Iterator<Item = String>) -> Result<Config, String> {
120:         let mut config = Config::default();
121:         let mut explicit_format: Option<Format> = None;
122:         let mut args = args;
123:         while let Some(arg) = args.next() {
124:             match arg.as_str() {
125:                 "--width" => config.width = parse_number(args.next(), "--width")?,
126:                 "--height" => config.height = parse_number(args.next(), "--height")?,
127:                 "--samples" => config.samples = parse_number(args.next(), "--samples")?,
128:                 "--output" => config.output = parse_value(args.next(), "--output")?,
129:                 "--format" => {
130:                     explicit_format = Some(match args.next().as_deref() {
131:                         Some("png") => Format::Png,
132:                         Some("ppm") => Format::Ppm,
133:                         _ => return Err("--format takes png or ppm".to_string()),
134:                     });
135:                 }
136:                 other => return Err(format!("unknown option: {other}")),
137:             }
138:         }
139:         if config.width < 2 {
140:             return Err("--width must be at least 2".to_string());
141:         }
142:         if config.height < 2 {
143:             return Err("--height must be at least 2".to_string());
144:         }
145:         if config.samples < 1 {
146:             return Err("--samples must be at least 1".to_string());
147:         }
148:         config.format = match explicit_format {
149:             Some(format) => format,
150:             None => match Path::new(&config.output)
151:                 .extension()
152:                 .and_then(|e| e.to_str())
153:             {
154:                 Some("png") => Format::Png,
155:                 Some("ppm") => Format::Ppm,
156:                 _ => return Err("--output must end in .png or .ppm".to_string()),
157:             },
158:         };
159:         Ok(config)
160:     }
161: }
